// The family-default QEMU CPU model: the -cpu fallback when an engine's
// --print-qemu-config names none. One definition, used by the plan executor's
// {qemu_cpu} fill and by cmd_profile's engine-synced launch.
inline constexpr const char* kDefaultQemuCpu = "andes-ax45mpv";

// hw-config sync: the QEMU fast leg models the hardware the accurate-leg
// engine measures, so its -cpu vlen follows that engine's descriptor. 512 is
// the fallback for engines that report none. One definition, used by both the
// plan executor ({vlen} fill) and the hybrid banner.
inline long synced_vlen(long engine_vlen) {
  return engine_vlen > 0 ? engine_vlen : 512;
}

// Fast-mode HVM (run --mode fast --engine vsim:...): the extra QEMU args that
// give the standalone fast QEMU a vsim engine's geometry -- `-cpu <model>,vlen=
// <synced>` (its vector width) and `-readconfig <cfg>` (the staged qemu.cfg
// carries the HVM window's hvm_size_pow_2, so 0x90000000 is backed at the
// engine's size). Empty cfg_path (probe/stage failed) -> {} so the caller
// errors out instead of running a no-HVM QEMU that would fault the workload's
// HVM stores. Empty cpu -> the family default model.
inline std::vector<std::string> fast_engine_qemu_extras(const std::string& cpu,
                                                        long vlen,
                                                        const std::string& cfg_path) {
  if (cfg_path.empty()) {
    return {};
  }
  const std::string model = cpu.empty() ? std::string(kDefaultQemuCpu) : cpu;
  return {"-cpu", model + ",vlen=" + std::to_string(synced_vlen(vlen)),
          "-readconfig", cfg_path};
}

// A trigger's per-leg argv contribution, dispatched by the leg's role. The
// QEMU plugin takes its trigger as a comma-suffix folded INTO the one `-plugin`
// token (so it rides the `{trigger}` placeholder); vsim takes separate tokens
// appended to its argv. marker contributes nothing (plugin/vsim detect the markers
// themselves).
struct LegTriggerArgs {
  std::string plugin_suffix;        // qemu fast-leg: appended to {trigger}
  std::vector<std::string> extra;   // vsim accurate-leg: appended tokens
};

// Map `t` onto `role`'s argv contribution. marker -> empty. pc -> qemu
// `,enter_pc=<enter_pc>` / vsim `--hybrid-exit-pc <exit_pc>`. Roles other
// than fast-leg/accurate-leg get nothing. A missing required param or an
// unknown trigger kind sets `err` (and returns an empty contribution).
//
// NOTE (altitude debt): these flag spellings are framework-side per-engine
// knowledge -- the one place F9 hardcodes a fast/accurate engine's CLI, unlike
// the base argv which comes from each engine's `--describe` invoke template.
// This is a deliberate scope cut: the principled form (per-(trigger,role) argv
// templates carried in `--describe`, filled by build_argv like `invoke`) would
// extend the F2 engine contract and is left for a later feature.
LegTriggerArgs leg_trigger_args(const Trigger& t, const std::string& role,
                                std::string& err);

// Turn an accurate engine's `<bin> --print-qemu-config` probe into a QEMU
// `-readconfig` file under `workdir`. On a clean probe (exit 0, non-empty
// stdout) writes `workdir/qemu.cfg` and returns its path; on any failure
// (engine without the flag -> the parser throws -> non-zero exit; timeout;
// spawn failure; empty output; unwritable dir) returns "" -- the tolerant
// fallback that leaves the fast leg on its descriptor's default -cpu.
std::string stage_qemu_cfg(const std::string& workdir, const RunResult& probe);

// The QEMU CPU model named by a `--print-qemu-config` probe's text: the first
